CREATE TABLE "engagement_organizations" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"tenant_opaque_id" text NOT NULL,"legal_name" text NOT NULL,"organization_type" text,"organization_address" text,"created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX "engagement_organizations_tenant_idx" ON "engagement_organizations" ("tenant_opaque_id");
CREATE TABLE "engagements" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"organization_id" uuid NOT NULL REFERENCES "engagement_organizations"("id"),"quote_request_id" uuid REFERENCES "quote_requests"("id"),"title" text NOT NULL,"state" text DEFAULT 'draft' NOT NULL,"quote_amount_cents" integer,"currency" text DEFAULT 'CAD' NOT NULL,"cost_centre_code" text,"created_at" timestamp with time zone DEFAULT now() NOT NULL,"updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX "engagements_quote_request_idx" ON "engagements" ("quote_request_id"); CREATE INDEX "engagements_organization_idx" ON "engagements" ("organization_id");
CREATE TABLE "engagement_scope_versions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"engagement_id" uuid NOT NULL REFERENCES "engagements"("id"),"version" integer NOT NULL,"status" text DEFAULT 'draft' NOT NULL,"terms" jsonb NOT NULL,"accepted_at" timestamp with time zone,"accepted_by" text,"created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX "engagement_scope_versions_unique" ON "engagement_scope_versions" ("engagement_id","version");
CREATE TABLE "engagement_milestones" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"engagement_id" uuid NOT NULL REFERENCES "engagements"("id"),"title" text NOT NULL,"status" text DEFAULT 'planned' NOT NULL,"amount_cents" integer,"evidence" jsonb,"due_at" timestamp with time zone,"accepted_at" timestamp with time zone,"created_at" timestamp with time zone DEFAULT now() NOT NULL); CREATE INDEX "engagement_milestones_engagement_idx" ON "engagement_milestones" ("engagement_id");
CREATE TABLE "engagement_change_orders" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"engagement_id" uuid NOT NULL REFERENCES "engagements"("id"),"description" text NOT NULL,"amount_cents" integer NOT NULL,"status" text DEFAULT 'requested' NOT NULL,"requested_at" timestamp with time zone DEFAULT now() NOT NULL,"decided_at" timestamp with time zone); CREATE INDEX "engagement_change_orders_engagement_idx" ON "engagement_change_orders" ("engagement_id");
CREATE TABLE "engagement_handoffs" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"engagement_id" uuid NOT NULL REFERENCES "engagements"("id"),"acceptance_criteria" jsonb NOT NULL,"status" text DEFAULT 'pending' NOT NULL,"response_note" text,"responded_at" timestamp with time zone,"created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE "engagement_invoices" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"engagement_id" uuid NOT NULL REFERENCES "engagements"("id"),"milestone_id" uuid REFERENCES "engagement_milestones"("id"),"amount_cents" integer NOT NULL,"status" text DEFAULT 'draft' NOT NULL,"approved_at" timestamp with time zone,"accounting_transaction_id" uuid,"created_at" timestamp with time zone DEFAULT now() NOT NULL); CREATE INDEX "engagement_invoices_engagement_idx" ON "engagement_invoices" ("engagement_id");
CREATE TABLE "engagement_payments" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"invoice_id" uuid NOT NULL REFERENCES "engagement_invoices"("id"),"amount_cents" integer NOT NULL,"reference" text NOT NULL,"received_at" timestamp with time zone NOT NULL,"reconciled_at" timestamp with time zone,"accounting_transaction_id" uuid,"created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE "engagement_audit_events" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"engagement_id" uuid NOT NULL REFERENCES "engagements"("id"),"action" text NOT NULL,"actor_type" text NOT NULL,"actor_reference" text NOT NULL,"payload" jsonb,"created_at" timestamp with time zone DEFAULT now() NOT NULL); CREATE INDEX "engagement_audit_events_timeline_idx" ON "engagement_audit_events" ("engagement_id","created_at");
CREATE TABLE "engagement_integration_inbox" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"integration" text NOT NULL,"event_id" text NOT NULL,"tenant_opaque_id" text NOT NULL,"event_type" text NOT NULL,"payload" jsonb NOT NULL,"status" text DEFAULT 'received' NOT NULL,"received_at" timestamp with time zone DEFAULT now() NOT NULL,"processed_at" timestamp with time zone); CREATE UNIQUE INDEX "engagement_inbox_idempotency_idx" ON "engagement_integration_inbox" ("integration","event_id");
CREATE TABLE "engagement_integration_outbox" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"engagement_id" uuid NOT NULL REFERENCES "engagements"("id"),"destination" text NOT NULL,"event_type" text NOT NULL,"payload" jsonb NOT NULL,"status" text DEFAULT 'pending' NOT NULL,"attempts" integer DEFAULT 0 NOT NULL,"last_error" text,"sent_at" timestamp with time zone,"created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE "engagement_posting_requests" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"invoice_id" uuid REFERENCES "engagement_invoices"("id"),"payment_id" uuid REFERENCES "engagement_payments"("id"),"status" text DEFAULT 'pending' NOT NULL,"reason" text,"accounting_transaction_id" uuid,"created_at" timestamp with time zone DEFAULT now() NOT NULL);